-- =====================================================================
-- ClinicScheduler V2: Schema (PostgreSQL port of db/mysql/schema_project.sql)
-- Target: PostgreSQL 14+
--
-- Creates the same 17 tables, keys and CHECK constraints as the MySQL
-- design. Apply once to an empty database (the app and the tests do this
-- through SqlScriptRunner); it does not drop anything.
--
-- What changes in the port:
--   * MySQL ENUM columns        -> PostgreSQL enum types
--   * AUTO_INCREMENT            -> GENERATED BY DEFAULT AS IDENTITY
--   * DATETIME                  -> timestamp (clinic-local wall clock)
--   * CURRENT_TIMESTAMP default -> clinic_now(), so the clinic's time does
--                                  not depend on the server's time zone
--   * JSON                      -> jsonb
--   * Two rules MySQL needed triggers for become declarative constraints:
--       - patient double-booking          -> exclusion constraint
--       - one pending cancellation / appt -> partial unique index
--     The triggers in 02_rules.sql still check them first, to give the
--     same readable error messages; the constraints make them race-proof.
-- =====================================================================

-- Lets an exclusion constraint combine "=" on an integer with "&&" on a range
CREATE EXTENSION IF NOT EXISTS btree_gist;

-- ---------------------------------------------------------------------
-- Clinic-local time. All three sites are in Houston, so timestamps are
-- stored as wall-clock time there, to the second (as MySQL DATETIME was).
-- ---------------------------------------------------------------------
CREATE FUNCTION clinic_now() RETURNS timestamp
LANGUAGE sql STABLE
AS $$ SELECT (now() AT TIME ZONE 'America/Chicago')::timestamp(0) $$;

-- ---------------------------------------------------------------------
-- Closed value sets
-- ---------------------------------------------------------------------
CREATE TYPE room_type           AS ENUM ('Standard', 'Infusion');
CREATE TYPE provider_credential AS ENUM ('MD', 'NP', 'PA', 'RN');
CREATE TYPE drug_class          AS ENUM ('Biologic', 'Corticosteroid', 'Premedication');
CREATE TYPE plan_status         AS ENUM ('Active', 'Completed', 'Discontinued');
CREATE TYPE appointment_status  AS ENUM ('Scheduled', 'Completed', 'Canceled', 'Missed');
CREATE TYPE dose_unit           AS ENUM ('mg', 'mg/kg', 'mL');
CREATE TYPE admin_route         AS ENUM ('IV', 'PO', 'Intra-articular');
CREATE TYPE admin_reason        AS ENUM ('Scheduled', 'As-needed');
CREATE TYPE request_status      AS ENUM ('Pending', 'Approved', 'Denied');
CREATE TYPE cancel_source       AS ENUM ('Patient', 'Clinic');
CREATE TYPE audit_action        AS ENUM ('INSERT', 'UPDATE', 'DELETE');

-- ---------------------------------------------------------------------
-- 1. location: the three Houston clinic sites
-- ---------------------------------------------------------------------
CREATE TABLE location (
  location_id             integer      GENERATED BY DEFAULT AS IDENTITY,
  name                    varchar(100) NOT NULL,
  street                  varchar(150) NOT NULL,
  city                    varchar(60)  NOT NULL DEFAULT 'Houston',
  state                   char(2)      NOT NULL DEFAULT 'TX',
  zip                     char(5)      NOT NULL,
  phone                   varchar(20)  NOT NULL,
  max_concurrent_patients smallint     NOT NULL DEFAULT 12,
  CONSTRAINT pk_location PRIMARY KEY (location_id),
  CONSTRAINT uq_location_name UNIQUE (name),
  CONSTRAINT ck_location_zip CHECK (zip ~ '^[0-9]{5}$'),
  CONSTRAINT ck_location_capacity CHECK (max_concurrent_patients > 0)
);

-- ---------------------------------------------------------------------
-- 2. room: belongs to one location; one infusion room per location
-- ---------------------------------------------------------------------
CREATE TABLE room (
  room_id     integer     GENERATED BY DEFAULT AS IDENTITY,
  location_id integer     NOT NULL,
  room_name   varchar(50) NOT NULL,
  room_type   room_type   NOT NULL DEFAULT 'Standard',
  capacity    smallint    NOT NULL DEFAULT 1,
  is_active   boolean     NOT NULL DEFAULT TRUE,
  CONSTRAINT pk_room PRIMARY KEY (room_id),
  CONSTRAINT uq_room_name_per_location UNIQUE (location_id, room_name),
  CONSTRAINT fk_room_location FOREIGN KEY (location_id)
    REFERENCES location (location_id),
  CONSTRAINT ck_room_capacity CHECK (capacity >= 1),
  -- Standard rooms hold one patient; infusion rooms hold up to three
  CONSTRAINT ck_room_type_capacity CHECK (
    (room_type = 'Standard' AND capacity = 1) OR
    (room_type = 'Infusion' AND capacity BETWEEN 1 AND 3))
);

-- ---------------------------------------------------------------------
-- 3. employee: supertype holding attributes shared by providers and staff
-- ---------------------------------------------------------------------
CREATE TABLE employee (
  employee_id integer      GENERATED BY DEFAULT AS IDENTITY,
  first_name  varchar(50)  NOT NULL,
  last_name   varchar(50)  NOT NULL,
  email       varchar(100) NOT NULL,
  phone       varchar(20)  NULL,
  hire_date   date         NOT NULL,
  is_active   boolean      NOT NULL DEFAULT TRUE,
  CONSTRAINT pk_employee PRIMARY KEY (employee_id),
  CONSTRAINT uq_employee_email UNIQUE (email),
  CONSTRAINT ck_employee_email CHECK (email LIKE '%_@_%._%')
);

-- ---------------------------------------------------------------------
-- 4. provider: subtype of employee (MD, NP, PA, RN)
-- ---------------------------------------------------------------------
CREATE TABLE provider (
  employee_id integer             NOT NULL,
  npi         char(10)            NOT NULL,
  credential  provider_credential NOT NULL,
  CONSTRAINT pk_provider PRIMARY KEY (employee_id),
  CONSTRAINT uq_provider_npi UNIQUE (npi),
  CONSTRAINT fk_provider_employee FOREIGN KEY (employee_id)
    REFERENCES employee (employee_id),
  CONSTRAINT ck_provider_npi CHECK (npi ~ '^[0-9]{10}$')
);

-- ---------------------------------------------------------------------
-- 5. staff: subtype of employee (front desk, scheduler, manager)
-- ---------------------------------------------------------------------
CREATE TABLE staff (
  employee_id integer     NOT NULL,
  job_title   varchar(60) NOT NULL,
  CONSTRAINT pk_staff PRIMARY KEY (employee_id),
  CONSTRAINT fk_staff_employee FOREIGN KEY (employee_id)
    REFERENCES employee (employee_id)
);

-- ---------------------------------------------------------------------
-- 6. employee_location: M:N between employee and location
-- ---------------------------------------------------------------------
CREATE TABLE employee_location (
  employee_id integer NOT NULL,
  location_id integer NOT NULL,
  CONSTRAINT pk_employee_location PRIMARY KEY (employee_id, location_id),
  CONSTRAINT fk_emploc_employee FOREIGN KEY (employee_id)
    REFERENCES employee (employee_id) ON DELETE CASCADE,
  CONSTRAINT fk_emploc_location FOREIGN KEY (location_id)
    REFERENCES location (location_id) ON DELETE CASCADE
);

-- ---------------------------------------------------------------------
-- 7. patient: each patient has one required home location
-- ---------------------------------------------------------------------
CREATE TABLE patient (
  patient_id       integer      GENERATED BY DEFAULT AS IDENTITY,
  home_location_id integer      NOT NULL,
  first_name       varchar(50)  NOT NULL,
  last_name        varchar(50)  NOT NULL,
  date_of_birth    date         NOT NULL,
  email            varchar(100) NULL,
  phone            varchar(20)  NOT NULL,
  street           varchar(150) NULL,
  city             varchar(60)  NULL,
  state            char(2)      NULL,
  zip              char(5)      NULL,
  is_active        boolean      NOT NULL DEFAULT TRUE,
  CONSTRAINT pk_patient PRIMARY KEY (patient_id),
  CONSTRAINT uq_patient_email UNIQUE (email),
  CONSTRAINT fk_patient_home_location FOREIGN KEY (home_location_id)
    REFERENCES location (location_id),
  CONSTRAINT ck_patient_zip CHECK (zip IS NULL OR zip ~ '^[0-9]{5}$')
);
CREATE INDEX idx_patient_name ON patient (last_name, first_name);

-- ---------------------------------------------------------------------
-- 8. service_type: rheumatology services and the room type each needs
-- ---------------------------------------------------------------------
CREATE TABLE service_type (
  service_type_id      integer     GENERATED BY DEFAULT AS IDENTITY,
  name                 varchar(60) NOT NULL,
  default_duration_min smallint    NOT NULL,
  required_room_type   room_type   NOT NULL DEFAULT 'Standard',
  is_active            boolean     NOT NULL DEFAULT TRUE,
  CONSTRAINT pk_service_type PRIMARY KEY (service_type_id),
  CONSTRAINT uq_service_type_name UNIQUE (name),
  -- Durations fit the 30-minute slot grid
  CONSTRAINT ck_service_duration CHECK (
    default_duration_min > 0 AND default_duration_min % 30 = 0)
);

-- ---------------------------------------------------------------------
-- 9. provider_qualification: M:N between provider and service_type
-- ---------------------------------------------------------------------
CREATE TABLE provider_qualification (
  employee_id     integer NOT NULL,
  service_type_id integer NOT NULL,
  CONSTRAINT pk_provider_qualification PRIMARY KEY (employee_id, service_type_id),
  CONSTRAINT fk_provqual_provider FOREIGN KEY (employee_id)
    REFERENCES provider (employee_id) ON DELETE CASCADE,
  CONSTRAINT fk_provqual_service FOREIGN KEY (service_type_id)
    REFERENCES service_type (service_type_id) ON DELETE CASCADE
);

-- ---------------------------------------------------------------------
-- 10. medication: catalog of drugs administered in clinic
-- ---------------------------------------------------------------------
CREATE TABLE medication (
  medication_id integer      GENERATED BY DEFAULT AS IDENTITY,
  generic_name  varchar(100) NOT NULL,
  brand_name    varchar(100) NULL,
  drug_class    drug_class   NOT NULL,
  is_active     boolean      NOT NULL DEFAULT TRUE,
  CONSTRAINT pk_medication PRIMARY KEY (medication_id),
  CONSTRAINT uq_medication_generic UNIQUE (generic_name)
);

-- ---------------------------------------------------------------------
-- 11. treatment_plan: header ordered by an MD, NP, or PA
-- ---------------------------------------------------------------------
CREATE TABLE treatment_plan (
  plan_id              integer     GENERATED BY DEFAULT AS IDENTITY,
  patient_id           integer     NOT NULL,
  ordering_provider_id integer     NOT NULL,
  start_date           date        NOT NULL,
  end_date             date        NULL,
  status               plan_status NOT NULL DEFAULT 'Active',
  notes                text        NULL,
  CONSTRAINT pk_treatment_plan PRIMARY KEY (plan_id),
  CONSTRAINT fk_plan_patient FOREIGN KEY (patient_id)
    REFERENCES patient (patient_id),
  CONSTRAINT fk_plan_provider FOREIGN KEY (ordering_provider_id)
    REFERENCES provider (employee_id),
  CONSTRAINT ck_plan_dates CHECK (end_date IS NULL OR end_date >= start_date)
);
CREATE INDEX idx_plan_patient ON treatment_plan (patient_id);

-- ---------------------------------------------------------------------
-- 12. treatment_plan_item: one recurring service at a fixed interval
-- ---------------------------------------------------------------------
CREATE TABLE treatment_plan_item (
  plan_item_id    integer  GENERATED BY DEFAULT AS IDENTITY,
  plan_id         integer  NOT NULL,
  service_type_id integer  NOT NULL,
  medication_id   integer  NULL,
  interval_weeks  smallint NOT NULL,
  total_sessions  smallint NULL,
  CONSTRAINT pk_plan_item PRIMARY KEY (plan_item_id),
  CONSTRAINT fk_planitem_plan FOREIGN KEY (plan_id)
    REFERENCES treatment_plan (plan_id) ON DELETE CASCADE,
  CONSTRAINT fk_planitem_service FOREIGN KEY (service_type_id)
    REFERENCES service_type (service_type_id),
  CONSTRAINT fk_planitem_medication FOREIGN KEY (medication_id)
    REFERENCES medication (medication_id),
  CONSTRAINT ck_planitem_interval CHECK (interval_weeks BETWEEN 1 AND 52),
  CONSTRAINT ck_planitem_sessions CHECK (total_sessions IS NULL OR total_sessions > 0)
);
CREATE INDEX idx_planitem_plan ON treatment_plan_item (plan_id);

-- ---------------------------------------------------------------------
-- 13. appointment: the central entity
--     Location is derived through room -> location (not stored, for 3NF).
-- ---------------------------------------------------------------------
CREATE TABLE appointment (
  appointment_id      integer            GENERATED BY DEFAULT AS IDENTITY,
  patient_id          integer            NOT NULL,
  provider_id         integer            NOT NULL,
  room_id             integer            NOT NULL,
  service_type_id     integer            NOT NULL,
  plan_item_id        integer            NULL,
  rescheduled_from_id integer            NULL,
  created_by          integer            NOT NULL,
  start_time          timestamp          NOT NULL,
  end_time            timestamp          NOT NULL,
  status              appointment_status NOT NULL DEFAULT 'Scheduled',
  created_at          timestamp          NOT NULL DEFAULT clinic_now(),
  notes               text               NULL,
  CONSTRAINT pk_appointment PRIMARY KEY (appointment_id),
  -- A missed appointment is rescheduled at most once (1:0..1)
  CONSTRAINT uq_appointment_rescheduled_from UNIQUE (rescheduled_from_id),
  CONSTRAINT fk_appt_patient FOREIGN KEY (patient_id)
    REFERENCES patient (patient_id),
  CONSTRAINT fk_appt_provider FOREIGN KEY (provider_id)
    REFERENCES provider (employee_id),
  CONSTRAINT fk_appt_room FOREIGN KEY (room_id)
    REFERENCES room (room_id),
  CONSTRAINT fk_appt_service FOREIGN KEY (service_type_id)
    REFERENCES service_type (service_type_id),
  CONSTRAINT fk_appt_plan_item FOREIGN KEY (plan_item_id)
    REFERENCES treatment_plan_item (plan_item_id),
  CONSTRAINT fk_appt_rescheduled_from FOREIGN KEY (rescheduled_from_id)
    REFERENCES appointment (appointment_id),
  CONSTRAINT fk_appt_created_by FOREIGN KEY (created_by)
    REFERENCES staff (employee_id),
  -- Time-slot rules: same weekday, 8 AM-5 PM, on :00 or :30
  CONSTRAINT ck_appt_order CHECK (end_time > start_time),
  CONSTRAINT ck_appt_same_day CHECK (start_time::date = end_time::date),
  CONSTRAINT ck_appt_weekday CHECK (EXTRACT(ISODOW FROM start_time) BETWEEN 1 AND 5),
  CONSTRAINT ck_appt_hours CHECK (
    start_time::time >= TIME '08:00' AND end_time::time <= TIME '17:00'),
  CONSTRAINT ck_appt_slot_grid CHECK (
    EXTRACT(MINUTE FROM start_time) IN (0, 30) AND EXTRACT(SECOND FROM start_time) = 0 AND
    EXTRACT(MINUTE FROM end_time)   IN (0, 30) AND EXTRACT(SECOND FROM end_time)   = 0),
  -- PostgreSQL only: a patient cannot be in two non-canceled visits at once.
  -- Declarative, so it holds even when two bookings commit at the same moment.
  CONSTRAINT ex_appt_patient_no_overlap EXCLUDE USING gist (
    patient_id WITH =,
    tsrange(start_time, end_time) WITH &&
  ) WHERE (status <> 'Canceled')
);
-- Indexes for conflict checks and schedule views
CREATE INDEX idx_appt_provider_time ON appointment (provider_id, start_time);
CREATE INDEX idx_appt_room_time     ON appointment (room_id, start_time);
CREATE INDEX idx_appt_patient_time  ON appointment (patient_id, start_time);
CREATE INDEX idx_appt_status_time   ON appointment (status, start_time);
CREATE INDEX idx_appt_plan_item     ON appointment (plan_item_id);

-- ---------------------------------------------------------------------
-- 14. medication_administration: one row per dose given
--     (M:N appointment-medication)
-- ---------------------------------------------------------------------
CREATE TABLE medication_administration (
  administration_id integer      GENERATED BY DEFAULT AS IDENTITY,
  appointment_id    integer      NOT NULL,
  medication_id     integer      NOT NULL,
  administered_by   integer      NOT NULL,
  dose              numeric(8,2) NOT NULL,
  dose_unit         dose_unit    NOT NULL,
  route             admin_route  NOT NULL,
  site              varchar(50)  NULL,
  lot_number        varchar(30)  NOT NULL,
  reason            admin_reason NOT NULL DEFAULT 'Scheduled',
  administered_at   timestamp    NOT NULL,
  CONSTRAINT pk_med_admin PRIMARY KEY (administration_id),
  CONSTRAINT fk_medadmin_appointment FOREIGN KEY (appointment_id)
    REFERENCES appointment (appointment_id),
  CONSTRAINT fk_medadmin_medication FOREIGN KEY (medication_id)
    REFERENCES medication (medication_id),
  CONSTRAINT fk_medadmin_provider FOREIGN KEY (administered_by)
    REFERENCES provider (employee_id),
  CONSTRAINT ck_medadmin_dose CHECK (dose > 0),
  -- Joint injections must record the injection site
  CONSTRAINT ck_medadmin_site CHECK (route <> 'Intra-articular' OR site IS NOT NULL)
);
CREATE INDEX idx_medadmin_medication_time ON medication_administration (medication_id, administered_at);
CREATE INDEX idx_medadmin_appointment     ON medication_administration (appointment_id);

-- ---------------------------------------------------------------------
-- 15. appointment_request: patient-submitted booking requests
-- ---------------------------------------------------------------------
CREATE TABLE appointment_request (
  request_id            integer        GENERATED BY DEFAULT AS IDENTITY,
  patient_id            integer        NOT NULL,
  service_type_id       integer        NOT NULL,
  preferred_location_id integer        NULL,
  preferred_start       timestamp      NOT NULL,
  patient_notes         text           NULL,
  status                request_status NOT NULL DEFAULT 'Pending',
  submitted_at          timestamp      NOT NULL DEFAULT clinic_now(),
  reviewed_by           integer        NULL,
  reviewed_at           timestamp      NULL,
  decision_note         varchar(255)   NULL,
  appointment_id        integer        NULL,
  CONSTRAINT pk_appointment_request PRIMARY KEY (request_id),
  -- An approved request produces at most one appointment (1:0..1)
  CONSTRAINT uq_apptreq_appointment UNIQUE (appointment_id),
  CONSTRAINT fk_apptreq_patient FOREIGN KEY (patient_id)
    REFERENCES patient (patient_id),
  CONSTRAINT fk_apptreq_service FOREIGN KEY (service_type_id)
    REFERENCES service_type (service_type_id),
  CONSTRAINT fk_apptreq_location FOREIGN KEY (preferred_location_id)
    REFERENCES location (location_id),
  CONSTRAINT fk_apptreq_reviewer FOREIGN KEY (reviewed_by)
    REFERENCES staff (employee_id),
  CONSTRAINT fk_apptreq_appointment FOREIGN KEY (appointment_id)
    REFERENCES appointment (appointment_id),
  -- Review fields must match the status
  CONSTRAINT ck_apptreq_status CHECK (
    (status = 'Pending'  AND reviewed_by IS NULL     AND reviewed_at IS NULL     AND appointment_id IS NULL) OR
    (status = 'Approved' AND reviewed_by IS NOT NULL AND reviewed_at IS NOT NULL AND appointment_id IS NOT NULL) OR
    (status = 'Denied'   AND reviewed_by IS NOT NULL AND reviewed_at IS NOT NULL AND appointment_id IS NULL)),
  CONSTRAINT ck_apptreq_review_time CHECK (reviewed_at IS NULL OR reviewed_at >= submitted_at)
);
CREATE INDEX idx_apptreq_status ON appointment_request (status, submitted_at);

-- ---------------------------------------------------------------------
-- 16. cancellation_request: from patients (reviewed) or the clinic
--     (approved automatically on insert)
-- ---------------------------------------------------------------------
CREATE TABLE cancellation_request (
  cancel_request_id integer        GENERATED BY DEFAULT AS IDENTITY,
  appointment_id    integer        NOT NULL,
  source            cancel_source  NOT NULL,
  submitted_by      integer        NULL,
  reason            varchar(255)   NOT NULL,
  status            request_status NOT NULL DEFAULT 'Pending',
  submitted_at      timestamp      NOT NULL DEFAULT clinic_now(),
  reviewed_by       integer        NULL,
  reviewed_at       timestamp      NULL,
  CONSTRAINT pk_cancellation_request PRIMARY KEY (cancel_request_id),
  CONSTRAINT fk_cancel_appointment FOREIGN KEY (appointment_id)
    REFERENCES appointment (appointment_id),
  CONSTRAINT fk_cancel_submitted_by FOREIGN KEY (submitted_by)
    REFERENCES staff (employee_id),
  CONSTRAINT fk_cancel_reviewed_by FOREIGN KEY (reviewed_by)
    REFERENCES staff (employee_id),
  -- Patient requests have no staff submitter; clinic requests must have one
  CONSTRAINT ck_cancel_source CHECK (
    (source = 'Patient' AND submitted_by IS NULL) OR
    (source = 'Clinic'  AND submitted_by IS NOT NULL)),
  -- Review fields must match the status
  CONSTRAINT ck_cancel_status CHECK (
    (status = 'Pending'  AND reviewed_by IS NULL     AND reviewed_at IS NULL) OR
    (status <> 'Pending' AND reviewed_by IS NOT NULL AND reviewed_at IS NOT NULL)),
  -- Clinic cancellations are approved by the staff member who submits them
  CONSTRAINT ck_cancel_clinic_auto CHECK (
    source = 'Patient' OR (status = 'Approved' AND reviewed_by = submitted_by)),
  CONSTRAINT ck_cancel_review_time CHECK (reviewed_at IS NULL OR reviewed_at >= submitted_at)
);
CREATE INDEX idx_cancel_status ON cancellation_request (status, submitted_at);
-- PostgreSQL only: at most one pending request per appointment. MySQL has no
-- partial unique indexes, so the original could only do this in a trigger.
CREATE UNIQUE INDEX uq_cancel_one_pending ON cancellation_request (appointment_id)
  WHERE status = 'Pending';

-- ---------------------------------------------------------------------
-- 17. audit_log: filled by triggers; changed_by comes from the session
--     setting app.current_employee_id (see current_employee_id())
-- ---------------------------------------------------------------------
CREATE TABLE audit_log (
  audit_id    bigint       GENERATED BY DEFAULT AS IDENTITY,
  table_name  varchar(64)  NOT NULL,
  record_id   integer      NOT NULL,
  action      audit_action NOT NULL,
  changed_by  integer      NULL,
  changed_at  timestamp    NOT NULL DEFAULT clinic_now(),
  old_values  jsonb        NULL,
  new_values  jsonb        NULL,
  CONSTRAINT pk_audit_log PRIMARY KEY (audit_id),
  CONSTRAINT fk_audit_employee FOREIGN KEY (changed_by)
    REFERENCES employee (employee_id)
);
CREATE INDEX idx_audit_record ON audit_log (table_name, record_id);
CREATE INDEX idx_audit_time   ON audit_log (changed_at);

-- ---------------------------------------------------------------------
-- Plain-language descriptions of the rules. They live in the database
-- with the rules themselves, so any client can show a rejected write in
-- words a person can act on without keeping its own copy of the rules.
-- ---------------------------------------------------------------------
COMMENT ON CONSTRAINT uq_location_name          ON location IS 'Two locations cannot share a name.';
COMMENT ON CONSTRAINT ck_location_zip           ON location IS 'A ZIP code is exactly five digits.';
COMMENT ON CONSTRAINT ck_location_capacity      ON location IS 'A location must allow at least one patient at a time.';
COMMENT ON CONSTRAINT uq_room_name_per_location ON room IS 'Two rooms at the same location cannot share a name.';
COMMENT ON CONSTRAINT ck_room_capacity          ON room IS 'A room holds at least one patient.';
COMMENT ON CONSTRAINT ck_room_type_capacity     ON room IS 'Standard rooms hold exactly one patient; infusion rooms hold one to three.';
COMMENT ON CONSTRAINT uq_employee_email         ON employee IS 'Two employees cannot share an email address.';
COMMENT ON CONSTRAINT ck_employee_email         ON employee IS 'The email address is not in a valid form.';
COMMENT ON CONSTRAINT uq_provider_npi           ON provider IS 'Two providers cannot share an NPI number.';
COMMENT ON CONSTRAINT ck_provider_npi           ON provider IS 'An NPI number is exactly ten digits.';
COMMENT ON CONSTRAINT uq_patient_email          ON patient IS 'Two patients cannot share an email address.';
COMMENT ON CONSTRAINT ck_patient_zip            ON patient IS 'A ZIP code is exactly five digits.';
COMMENT ON CONSTRAINT uq_service_type_name      ON service_type IS 'Two services cannot share a name.';
COMMENT ON CONSTRAINT ck_service_duration       ON service_type IS 'A service lasts a positive multiple of 30 minutes.';
COMMENT ON CONSTRAINT uq_medication_generic     ON medication IS 'Two medications cannot share a generic name.';
COMMENT ON CONSTRAINT ck_plan_dates             ON treatment_plan IS 'A plan cannot end before it starts.';
COMMENT ON CONSTRAINT ck_planitem_interval      ON treatment_plan_item IS 'A plan item repeats every 1 to 52 weeks.';
COMMENT ON CONSTRAINT ck_planitem_sessions      ON treatment_plan_item IS 'A session limit, when given, must be at least one.';
COMMENT ON CONSTRAINT uq_appointment_rescheduled_from ON appointment IS 'A missed appointment can be rescheduled only once.';
COMMENT ON CONSTRAINT ck_appt_order             ON appointment IS 'An appointment must end after it starts.';
COMMENT ON CONSTRAINT ck_appt_same_day          ON appointment IS 'An appointment must start and end on the same day.';
COMMENT ON CONSTRAINT ck_appt_weekday           ON appointment IS 'The clinic is open Monday to Friday only.';
COMMENT ON CONSTRAINT ck_appt_hours             ON appointment IS 'Appointments must fall between 8:00 AM and 5:00 PM.';
COMMENT ON CONSTRAINT ck_appt_slot_grid         ON appointment IS 'Appointments start and end on the hour or half hour.';
COMMENT ON CONSTRAINT ex_appt_patient_no_overlap ON appointment IS 'A patient cannot have two appointments at the same time.';
COMMENT ON CONSTRAINT ck_medadmin_dose          ON medication_administration IS 'A dose must be greater than zero.';
COMMENT ON CONSTRAINT ck_medadmin_site          ON medication_administration IS 'A joint injection must record the injection site.';
COMMENT ON CONSTRAINT uq_apptreq_appointment    ON appointment_request IS 'An appointment can come from only one request.';
COMMENT ON CONSTRAINT ck_apptreq_status         ON appointment_request IS 'A pending request has no reviewer; an approved one names its reviewer and appointment; a denied one names its reviewer.';
COMMENT ON CONSTRAINT ck_apptreq_review_time    ON appointment_request IS 'A request cannot be reviewed before it was submitted.';
COMMENT ON CONSTRAINT ck_cancel_source          ON cancellation_request IS 'A clinic cancellation names the staff member who submitted it; a patient request does not.';
COMMENT ON CONSTRAINT ck_cancel_status          ON cancellation_request IS 'A pending request has no reviewer; a decided one names who reviewed it and when.';
COMMENT ON CONSTRAINT ck_cancel_clinic_auto     ON cancellation_request IS 'A clinic cancellation is approved by the staff member who submits it.';
COMMENT ON CONSTRAINT ck_cancel_review_time     ON cancellation_request IS 'A request cannot be reviewed before it was submitted.';
COMMENT ON INDEX uq_cancel_one_pending IS 'An appointment can have only one pending cancellation request.';
